package loadtest

import (
	"context"
	"encoding/binary"
	"errors"
	"fmt"
	"sync/atomic"
	"time"
)

const (
	movementPacketMarker = 0x4d
	shootingPacketMarker = 0x53
	ipv4UDPHeaderBytes   = 28
	maxGameplayPacket    = 2048
)

// GameplayConfig controls the continuous peer traffic generated by each
// player after a round starts and before the scripted round-ending kill.
type GameplayConfig struct {
	Duration                 time.Duration
	MovementPacketsPerSecond int
	MovementPayloadBytes     int
	ShootingPacketsPerSecond int
	ShootingPayloadBytes     int
}

func (config GameplayConfig) enabled() bool { return config.Duration > 0 }

type gameplayPhaseMetrics struct {
	activeNanos atomic.Int64
}

type udpCounters struct {
	registrationPacketsSent     atomic.Uint64
	registrationPacketsReceived atomic.Uint64
	movementPacketsSent         atomic.Uint64
	movementBytesSent           atomic.Uint64
	movementPacketsReceived     atomic.Uint64
	movementBytesReceived       atomic.Uint64
	shootingPacketsSent         atomic.Uint64
	shootingBytesSent           atomic.Uint64
	shootingPacketsReceived     atomic.Uint64
	shootingBytesReceived       atomic.Uint64
	expectedRelayPackets        atomic.Uint64
	expectedRelayBytes          atomic.Uint64
	sendErrors                  atomic.Uint64
	readErrors                  atomic.Uint64
}

func runGameplayTraffic(ctx context.Context, groups []*clientGroup, config GameplayConfig, phases *gameplayPhaseMetrics) error {
	if !config.enabled() {
		return nil
	}
	started := time.Now()
	err := runGroups(groups, func(group *clientGroup) error {
		return runGroupGameplayTraffic(ctx, group, config)
	})
	phases.activeNanos.Add(int64(time.Since(started)))
	return err
}

func runGroupGameplayTraffic(ctx context.Context, group *clientGroup, config GameplayConfig) error {
	var movementTicker, shootingTicker *time.Ticker
	var movement, shooting <-chan time.Time
	if config.MovementPacketsPerSecond > 0 {
		movementTicker = time.NewTicker(time.Second / time.Duration(config.MovementPacketsPerSecond))
		movement = movementTicker.C
		defer movementTicker.Stop()
	}
	if config.ShootingPacketsPerSecond > 0 {
		shootingTicker = time.NewTicker(time.Second / time.Duration(config.ShootingPacketsPerSecond))
		shooting = shootingTicker.C
		defer shootingTicker.Stop()
	}

	finished := time.NewTimer(config.Duration)
	defer finished.Stop()
	var movementSequence, shootingSequence uint32
	for {
		select {
		case <-movement:
			movementSequence++
			if err := sendGroupGameplayPacket(group, movementPacketMarker, config.MovementPayloadBytes, movementSequence); err != nil {
				return err
			}
		case <-shooting:
			shootingSequence++
			if err := sendGroupGameplayPacket(group, shootingPacketMarker, config.ShootingPayloadBytes, shootingSequence); err != nil {
				return err
			}
		case <-finished.C:
			return nil
		case <-ctx.Done():
			return ctx.Err()
		}
	}
}

func sendGroupGameplayPacket(group *clientGroup, marker byte, payloadBytes int, sequence uint32) error {
	recipients := len(group.clients) - 1
	errorsByClient := make([]error, len(group.clients))
	for index, client := range group.clients {
		packet := gameplayPacket(marker, payloadBytes, client.index, sequence)
		errorsByClient[index] = client.sendGameplayPacket(packet, marker, recipients)
	}
	return errors.Join(errorsByClient...)
}

func gameplayPacket(marker byte, size, clientIndex int, sequence uint32) []byte {
	packet := make([]byte, size)
	packet[0] = marker
	packet[1] = 1 // load-traffic schema version
	binary.LittleEndian.PutUint32(packet[2:6], uint32(clientIndex))
	binary.LittleEndian.PutUint32(packet[6:10], sequence)
	for index := 10; index < len(packet); index++ {
		packet[index] = byte(clientIndex + int(sequence) + index)
	}
	return packet
}

func buildGameplayReport(config GameplayConfig, clients []*loadClient, phases *gameplayPhaseMetrics, cycles int) GameplayReport {
	report := GameplayReport{
		Enabled:                  config.enabled(),
		DurationPerRoom:          config.Duration,
		ActiveDuration:           time.Duration(phases.activeNanos.Load()),
		MovementPacketsPerSecond: config.MovementPacketsPerSecond,
		MovementPayloadBytes:     config.MovementPayloadBytes,
		ShootingPacketsPerSecond: config.ShootingPacketsPerSecond,
		ShootingPayloadBytes:     config.ShootingPayloadBytes,
	}
	if !report.Enabled {
		return report
	}
	for _, client := range clients {
		if client == nil {
			continue
		}
		counters := &client.udpCounters
		report.RegistrationPacketsSent += counters.registrationPacketsSent.Load()
		report.RegistrationPacketsReceived += counters.registrationPacketsReceived.Load()
		report.MovementPacketsSent += counters.movementPacketsSent.Load()
		report.MovementPacketsReceived += counters.movementPacketsReceived.Load()
		report.ShootingPacketsSent += counters.shootingPacketsSent.Load()
		report.ShootingPacketsReceived += counters.shootingPacketsReceived.Load()
		report.ClientPayloadBytesSent += counters.movementBytesSent.Load() + counters.shootingBytesSent.Load()
		report.ExpectedRelayPackets += counters.expectedRelayPackets.Load()
		report.ExpectedRelayPayloadBytes += counters.expectedRelayBytes.Load()
		report.ReceivedRelayPayloadBytes += counters.movementBytesReceived.Load() + counters.shootingBytesReceived.Load()
		report.SendErrors += counters.sendErrors.Load()
		report.ReadErrors += counters.readErrors.Load()
	}
	report.ReceivedRelayPackets = report.MovementPacketsReceived + report.ShootingPacketsReceived
	report.ExpectedRelayIPv4Bytes = report.ExpectedRelayPayloadBytes + report.ExpectedRelayPackets*ipv4UDPHeaderBytes
	report.ReceivedRelayIPv4Bytes = report.ReceivedRelayPayloadBytes + report.ReceivedRelayPackets*ipv4UDPHeaderBytes
	if report.ExpectedRelayPackets > 0 {
		report.DeliveryRatio = float64(report.ReceivedRelayPackets) / float64(report.ExpectedRelayPackets)
	}
	if report.ActiveDuration > 0 {
		seconds := report.ActiveDuration.Seconds()
		report.ExpectedAggregateMegabits = float64(report.ExpectedRelayIPv4Bytes*8) / seconds / 1_000_000
		report.DeliveredAggregateMegabits = float64(report.ReceivedRelayIPv4Bytes*8) / seconds / 1_000_000
	}
	playerSeconds := config.Duration.Seconds() * float64(len(clients)) * float64(cycles)
	if playerSeconds > 0 {
		report.ExpectedPerPlayerKilobits = float64(report.ExpectedRelayIPv4Bytes*8) / playerSeconds / 1_000
		// At a constant rate for a 30-day month, 1 Kbps equals 0.000324 TB.
		report.ProjectedMonthlyEgressTB = report.ExpectedPerPlayerKilobits * float64(len(clients)) * 0.000324
	}
	return report
}

func validateGameplayConfig(config GameplayConfig) error {
	switch {
	case config.Duration < 0:
		return errors.New("gameplay duration must not be negative")
	case !config.enabled():
		return nil
	case config.MovementPacketsPerSecond < 0 || config.MovementPacketsPerSecond > 1000:
		return fmt.Errorf("movement packet rate %d is outside 0..1000", config.MovementPacketsPerSecond)
	case config.ShootingPacketsPerSecond < 0 || config.ShootingPacketsPerSecond > 1000:
		return fmt.Errorf("shooting packet rate %d is outside 0..1000", config.ShootingPacketsPerSecond)
	case config.MovementPacketsPerSecond == 0 && config.ShootingPacketsPerSecond == 0:
		return errors.New("gameplay requires a movement or shooting packet rate")
	case config.MovementPacketsPerSecond > 0 && (config.MovementPayloadBytes < 10 || config.MovementPayloadBytes > maxGameplayPacket):
		return fmt.Errorf("movement payload size %d is outside 10..%d", config.MovementPayloadBytes, maxGameplayPacket)
	case config.ShootingPacketsPerSecond > 0 && (config.ShootingPayloadBytes < 10 || config.ShootingPayloadBytes > maxGameplayPacket):
		return fmt.Errorf("shooting payload size %d is outside 10..%d", config.ShootingPayloadBytes, maxGameplayPacket)
	default:
		return nil
	}
}
